-- 306: Original BrillaPrep WASSCE BrillaPrep transitional Clerical Office Duties beta content blueprint questions, part 6.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_306_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_306_guard;
INSERT INTO _migration_306_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_clerical_b005_026' AND NOT (q.topic_id IS 'topic_was_clerical_b005_6' AND q.subject_id IS 'subj_wassce_clerical' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the purpose of an imprest petty-cash system?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. To explain differences between the cash-book balance and the bank statement","B. To restore the float to a fixed amount by reimbursing documented spending","C. A statutory deduction remitted to the tax authority","D. A properly authorised petty-cash voucher with evidence of the expense"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Under imprest, vouchers plus cash should equal the authorised float, making shortages and unsupported payments visible. Therefore the correct answer is B: To restore the float to a fixed amount by reimbursing documented spending.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_clerical_b005_6' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_clerical_b005_026' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Clerical Office Duties practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2023/03/Business21.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_306_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_clerical_b005_027' AND NOT (q.topic_id IS 'topic_was_clerical_b005_6' AND q.subject_id IS 'subj_wassce_clerical' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why is a bank reconciliation prepared?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A statutory deduction remitted to the tax authority","B. A properly authorised petty-cash voucher with evidence of the expense","C. To explain differences between the cash-book balance and the bank statement","D. Separation of duties reduces the opportunity for undetected error or fraud"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Timing items and errors are identified so the organisation can establish the corrected bank position. Therefore the correct answer is C: To explain differences between the cash-book balance and the bank statement.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_clerical_b005_6' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_clerical_b005_027' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Clerical Office Duties practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2023/03/Business21.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_306_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_clerical_b005_028' AND NOT (q.topic_id IS 'topic_was_clerical_b005_6' AND q.subject_id IS 'subj_wassce_clerical' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is income tax deducted from pay?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A properly authorised petty-cash voucher with evidence of the expense","B. Separation of duties reduces the opportunity for undetected error or fraud","C. To restore the float to a fixed amount by reimbursing documented spending","D. A statutory deduction remitted to the tax authority"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Income tax is withheld under law and is not an optional office welfare contribution or a supplier discount. Therefore the correct answer is D: A statutory deduction remitted to the tax authority.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_clerical_b005_6' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_clerical_b005_028' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Clerical Office Duties practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2023/03/Business21.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_306_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_clerical_b005_029' AND NOT (q.topic_id IS 'topic_was_clerical_b005_6' AND q.subject_id IS 'subj_wassce_clerical' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which document supports a small petty-cash payment?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A properly authorised petty-cash voucher with evidence of the expense","B. Separation of duties reduces the opportunity for undetected error or fraud","C. To restore the float to a fixed amount by reimbursing documented spending","D. To explain differences between the cash-book balance and the bank statement"]' AND q.correct_answer IS 'A' AND q.explanation IS 'The voucher records purpose, amount, date and approval, creating an audit trail for the reduction in cash. Therefore the correct answer is A: A properly authorised petty-cash voucher with evidence of the expense.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_clerical_b005_6' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_clerical_b005_029' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Clerical Office Duties practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2023/03/Business21.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_306_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_clerical_b005_030' AND NOT (q.topic_id IS 'topic_was_clerical_b005_6' AND q.subject_id IS 'subj_wassce_clerical' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why should the person approving payments differ from the person recording them where practical?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. To restore the float to a fixed amount by reimbursing documented spending","B. Separation of duties reduces the opportunity for undetected error or fraud","C. To explain differences between the cash-book balance and the bank statement","D. A statutory deduction remitted to the tax authority"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Independent roles create a checking relationship so one person cannot initiate and conceal an improper transaction alone. Therefore the correct answer is B: Separation of duties reduces the opportunity for undetected error or fraud.' AND q.difficulty IS 'hard' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_clerical_b005_6' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_clerical_b005_030' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Clerical Office Duties practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2023/03/Business21.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
